def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    dangerous_bids = []
    low_budget_count = 0
    rich_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('budget', 0) < DAILY_SALARY * 0.8:
                low_budget_count += 1
            if opp.get('budget', 0) > DAILY_SALARY * 4:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                    dangerous_bids.append(float(bid))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.35))

    units = supply / float(WATER_REQ)
    scarcity = 0
    if units <= 1.2:
        scarcity = 2
    elif units <= 1.6:
        scarcity = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
    danger_prev = max(dangerous_bids) if dangerous_bids else 0.0

    urgency = 0
    if hp <= 2 or no_water >= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    base = DAILY_SALARY * 0.42

    if urgency >= 3:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif urgency == 2:
        if scarcity >= 1:
            bid = max(DAILY_SALARY * 0.82, second_prev + 1.5)
        else:
            bid = max(DAILY_SALARY * 0.72, danger_prev + 1.0)
    else:
        if scarcity >= 2:
            bid = max(DAILY_SALARY * 0.68, second_prev + 1.0)
        elif scarcity == 1:
            bid = max(base, min(DAILY_SALARY * 0.75, second_prev + 0.5))
        else:
            if highest_prev >= DAILY_SALARY * 1.2:
                bid = DAILY_SALARY * 0.28
            elif highest_prev >= DAILY_SALARY * 0.9:
                bid = DAILY_SALARY * 0.34
            else:
                bid = max(DAILY_SALARY * 0.45, second_prev + 0.75)

    if low_budget_count >= 2 and urgency == 0:
        bid *= 0.88
    if rich_count >= 2 and scarcity >= 1:
        bid *= 1.08

    if day >= 8 and hp >= 6 and no_water == 0:
        bid *= 0.92

    reserve = 0.0
    if urgency == 0:
        reserve = DAILY_SALARY * 1.2
    elif urgency == 1:
        reserve = DAILY_SALARY * 0.8
    elif urgency == 2:
        reserve = DAILY_SALARY * 0.3

    cap = budget - reserve
    if cap < 0:
        cap = budget

    bid = min(bid, cap)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = float(my_status.get('no_water_days', 0.0))

    alive = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive.append(opp)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = 0.0
    if len(prev_bids) >= 2:
        sorted_b = sorted(prev_bids, reverse=True)
        second_prev_bid = sorted_b[1]

    # Pressure estimate: if someone previously bid very high, they likely value survival
    # Use that to slightly outbid, but cap by what we can afford.
    # Supply factor: higher supply reduces urgency to overbid.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_ratio < 0.0:
        supply_ratio = 0.0
    if supply_ratio > 1.0:
        supply_ratio = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency = 1.0
    elif hp <= 4:
        urgency = 0.7
    elif hp <= 7:
        urgency = 0.45
    else:
        urgency = 0.25

    # If we've already gone without water, urgency increases sharply.
    if no_water_days >= 2:
        urgency = min(1.0, urgency + 0.35)
    elif no_water_days >= 1:
        urgency = min(1.0, urgency + 0.15)

    # Base bid target
    # If highest_prev_bid suggests strong competition, aim near it; otherwise bid moderately.
    # Outbid by a small increment to win when needed.
    increment = 2.5

    # Determine target competition level
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Someone was willing to spend a lot; match/just-above highest to secure.
        target = highest_prev_bid + increment * (1.0 - supply_ratio)
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        # Medium competition: outbid around second-highest (or highest if only one)
        base = second_prev_bid if second_prev_bid > 0.0 else highest_prev_bid
        target = base + increment * (0.8 - 0.6 * supply_ratio) + 1.0
    else:
        # Low competition: bid based on urgency and supply
        target = DAILY_SALARY * (0.35 + 0.35 * urgency) * (0.9 - 0.25 * supply_ratio)

    # Adjust for supply: when supply is high, we can bid less; when low, bid more.
    # Convert supply to expected water units pressure: lower supply => more scarcity.
    scarcity = 1.0
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = 1.0 - supply_ratio
    scarcity = max(0.0, min(1.0, scarcity))
    target = target * (0.85 + 0.3 * scarcity)

    # Ensure we don't bid above what we can afford.
    # Also, if budget is very low, bid whatever keeps us from wasting too much.
    if budget <= 0.0:
        return 0.0

    # Budget-aware cap: avoid committing entire budget unless urgency is extreme.
    if urgency >= 0.9:
        max_commit = budget
    else:
        max_commit = min(budget, DAILY_SALARY * (0.9 + 0.2 * urgency))

    bid = min(max_commit, target)

    # If hp is very low, ensure we bid at least a meaningful amount to avoid losing.
    if hp <= 2:
        min_bid = min(budget, DAILY_SALARY * 0.75)
        if bid < min_bid:
            bid = min_bid

    # Keep non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    # Identify alive opponents
    alive = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive:
        return min(budget, DAILY_SALARY * 0.3)

    # Get yesterday's max bid from alive opponents
    prev_bids = []
    for opp in alive.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])
    if not prev_bids:
        # No data, use conservative aggressive
        base_bid = DAILY_SALARY * 0.7
    else:
        max_prev = max(prev_bids)
        # Adjust based on how competitive
        if max_prev > DAILY_SALARY * 0.9:
            base_bid = max_prev + 2
        else:
            base_bid = max_prev + 5

    # Consider desperation
    if hp <= 2 or no_water_days >= 1:
        bid = min(budget, base_bid * 1.3)
    elif hp <= 5:
        bid = min(budget, base_bid * 1.1)
    else:
        bid = min(budget, base_bid * 0.9)

    # Ensure at least a minimum bid to compete if budget allows
    min_bid = DAILY_SALARY * 0.3
    if bid < min_bid and budget >= min_bid:
        bid = min_bid

    return min(bid, budget)
